import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x91a69f);scene.fog=new THREE.FogExp2(0x91a69f,.018);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc8d7ce,0x293d37,2.1));
const sun=new THREE.DirectionalLight(0xffdfb1,3.0);sun.position.set(-18,28,12);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=42;sun.shadow.camera.bottom=-50;scene.add(sun);
const mats={sand:new THREE.MeshStandardMaterial({color:0x857a5d,roughness:.98}),road:new THREE.MeshStandardMaterial({color:0x4c5148,roughness:.95}),dark:new THREE.MeshStandardMaterial({color:0x293532,roughness:.8}),steel:new THREE.MeshStandardMaterial({color:0x59665d,metalness:.5,roughness:.6}),rust:new THREE.MeshStandardMaterial({color:0x765844,metalness:.25,roughness:.8}),grass:new THREE.MeshStandardMaterial({color:0x53634b,roughness:1}),water:new THREE.MeshStandardMaterial({color:0x385b5c,roughness:.26,metalness:.18,transparent:true,opacity:.91}),lime:new THREE.MeshStandardMaterial({color:0xc7e36a,emissive:0x526827,emissiveIntensity:1.6}),red:new THREE.MeshStandardMaterial({color:0xd77950,emissive:0x682511,emissiveIntensity:1.1})};
function box(parent,x,y,z,w,h,d,mat,rotY=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.rotation.y=rotY;m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cyl(parent,x,y,z,r1,r2,h,mat,seg=10){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,mat){const m=new THREE.Mesh(new THREE.SphereGeometry(r,10,8),mat);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
const ground=new THREE.Mesh(new THREE.PlaneGeometry(125,145),mats.sand);ground.rotation.x=-Math.PI/2;ground.position.set(0,-.28,-17);ground.receiveShadow=true;scene.add(ground);
const water=new THREE.Mesh(new THREE.PlaneGeometry(150,160),mats.water);water.rotation.x=-Math.PI/2;water.position.set(0,-.42,-18);scene.add(water);
// Raised broken causeway through the flooded marsh.
box(scene,0,-.02,-17,13,.44,83,mats.road);
for(let z=-57;z<25;z+=4){box(scene,0,.205,z,.12,.02,1.2,new THREE.MeshStandardMaterial({color:0xb8a979,roughness:1}))}
// Gravel shoulders, tidal grass, eroded banks and scattered barriers.
for(let i=0;i<130;i++){const x=(Math.random()<.5?-1:1)*(7+Math.random()*23),z=-58+Math.random()*82;const r=.15+Math.random()*.75;const rock=sphere(scene,x,-.1,z,r,new THREE.MeshStandardMaterial({color:[0x575b4b,0x77705a,0x414e48][i%3],roughness:1}));rock.scale.y=.35;}
for(let i=0;i<75;i++){let x=(Math.random()<.5?-1:1)*(6+Math.random()*13),z=-57+Math.random()*80;let reed=cyl(scene,x,.25,z,.025,.08,.8+Math.random()*.8,mats.grass,5);reed.rotation.z=(Math.random()-.5)*.24;}
for(const z of [-4,-24,-44]){for(const side of [-1,1]){box(scene,side*6.2,.65,z,1.1,1.3,1.7,mats.rust,.25);box(scene,side*5.45,.38,z+1,.18,.7,.2,mats.steel);}}
// distant shoreline silhouettes and utility poles
for(let i=0;i<28;i++){const x=(i%2?1:-1)*(20+Math.random()*35),z=-67+Math.random()*105,h=2+Math.random()*6;box(scene,x,h/2-.2,z,2+Math.random()*4,h,2+Math.random()*4,i%3===0?mats.dark:mats.grass,Math.random());}
for(const x of [-10.5,10.5]){for(let z=-52;z<23;z+=19){cyl(scene,x,3,z,.12,.18,6,mats.dark,7);box(scene,x,5.6,z,3,.12,.14,mats.dark);}}
// A wreck and field dressing give the route useful cover.
const wreck=new THREE.Group();wreck.position.set(4.5,.1,-11);wreck.rotation.y=-.35;scene.add(wreck);box(wreck,0,.5,0,3.4,.75,1.5,mats.rust);box(wreck,0,1.02,-.25,1.6,.45,1.45,mats.dark);for(const x of [-1.1,1.1])cyl(wreck,x,.17,.48,.35,.35,.18,mats.dark,12).rotation.z=Math.PI/2;
for(const z of [3,-18,-37]){box(scene,-3.3,.55,z,1.3,1.1,.22,mats.dark);box(scene,-3.3,1.13,z,.12,.12,.3,mats.steel);}
// relay towers at each point
const relays=[];
function makeRelay(z,index){const g=new THREE.Group();g.position.set(0,0,z);scene.add(g);cyl(g,0,.95,0,.19,.28,1.9,mats.steel);box(g,0,2.05,0,.9,.42,.55,mats.dark);box(g,0,2.15,0,.52,.08,.58,mats.lime);cyl(g,0,3.1,0,.035,.035,1.8,mats.steel,7);sphere(g,0,4.05,0,.31,index===0?mats.red:mats.lime);for(let a=0;a<4;a++){let angle=a*Math.PI/2;box(g,Math.cos(angle)*1.25,.04,Math.sin(angle)*1.25,.12,.08,.12,mats.lime);}const ring=new THREE.Mesh(new THREE.TorusGeometry(2.1,.055,6,36),mats.lime);ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);const light=new THREE.PointLight(0xbde95b,1.8,8);light.position.y=3.8;g.add(light);relays.push({group:g,z,ring,light,index,active:false});}
[-2,-21,-40].forEach((z,i)=>makeRelay(z,i));
// Extraction flare at the end of the road
const extract=new THREE.Group();extract.position.set(0,0,-51);scene.add(extract);box(extract,-2,1.6,0,.16,3.2,.16,mats.steel);box(extract,2,1.6,0,.16,3.2,.16,mats.steel);box(extract,0,3.15,0,4.2,.18,.18,mats.steel);const exlight=new THREE.PointLight(0xffae64,0,12);exlight.position.y=2.8;extract.add(exlight);sphere(extract,0,2.9,0,.22,mats.red);
// Player first-person weapon model
const gun=new THREE.Group();camera.add(gun);scene.add(camera);box(gun,.34,-.29,-.62,.17,.17,.82,mats.dark);box(gun,.35,-.24,-.91,.075,.075,.6,mats.steel);box(gun,.32,-.44,-.45,.1,.32,.13,mats.dark);box(gun,.25,-.16,-.55,.08,.08,.13,mats.rust);gun.position.set(0,0,0);

const player={pos:new THREE.Vector3(0,0,13),health:100,ammo:30,reserve:120,dead:false};camera.position.set(0,1.65,13);let yaw=0,pitch=0,started=false,locked=false,fireDown=false,lastShot=0,reloading=false,pulseLeft=0,pulseCooldown=0,elapsed=0,objectiveIndex=0,capture=0,tide=180,gameOver=false,hitFlash=0,toastTimer=0,shotKick=0;
const keys={};const enemies=[],enemyBullets=[],effects=[];const raycaster=new THREE.Raycaster();raycaster.far=48;
const $=s=>document.querySelector(s);const toastEl=$('#toast');
function toast(text){toastEl.textContent=text;toastEl.classList.add('show');toastTimer=2.2;}
function startGame(){if(started)return;started=true;$('#intro').classList.add('hidden');if(innerWidth>740)renderer.domElement.requestPointerLock?.();toast('SECURE THE FIRST RELAY');}
$('#deploy').addEventListener('click',startGame);$('#restart').addEventListener('click',()=>location.reload());
renderer.domElement.addEventListener('click',()=>{if(started&&!locked&&innerWidth>740)renderer.domElement.requestPointerLock?.()});document.addEventListener('pointerlockchange',()=>locked=document.pointerLockElement===renderer.domElement);
document.addEventListener('mousemove',e=>{if(locked&&started){yaw-=e.movementX*.0022;pitch-=e.movementY*.0019;pitch=THREE.MathUtils.clamp(pitch,-1.15,1.15)}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(!e.repeat&&e.code==='KeyQ')usePulse();if(!e.repeat&&e.code==='KeyR')reload();if(e.code==='Escape'&&started&&!gameOver&&innerWidth>740){$('#intro').classList.remove('hidden');$('#intro').querySelector('h2').innerHTML='PAUSED<br /><em>RANGER.</em>';$('#intro').querySelector('p').textContent='The tide keeps moving. Resume when you are ready.';$('#deploy').textContent='RESUME MISSION →';$('#deploy').onclick=()=>{ $('#intro').classList.add('hidden');if(innerWidth>740)renderer.domElement.requestPointerLock?.()}}});document.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('mousedown',e=>{if(e.button===0&&started&&!gameOver){fireDown=true;shoot()}});document.addEventListener('mouseup',e=>{if(e.button===0)fireDown=false});
function bindHold(id,fn){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();fn(true)});['pointerup','pointercancel','pointerleave'].forEach(ev=>el.addEventListener(ev,e=>{e.preventDefault();fn(false)}))}
bindHold('#touch-fire',v=>{fireDown=v;if(v)shoot()});$('#touch-pulse').addEventListener('pointerdown',e=>{e.preventDefault();usePulse()});$('#touch-reload').addEventListener('pointerdown',e=>{e.preventDefault();reload()});document.querySelectorAll('[data-move]').forEach(b=>{const code={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[b.dataset.move];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[code]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>keys[code]=false))});
function makeEnemy(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const uniform=new THREE.MeshStandardMaterial({color:0x443f38,roughness:.9}),skin=new THREE.MeshStandardMaterial({color:0x95745d,roughness:1}),gear=new THREE.MeshStandardMaterial({color:0x262b27,roughness:.8});const body=new THREE.Mesh(new THREE.CylinderGeometry(.28,.34,.95,8),uniform);body.position.y=1.13;body.castShadow=true;g.add(body);const head=sphere(g,0,1.82,0,.24,skin);const helmet=sphere(g,0,2.0,0,.26,gear);helmet.scale.y=.48;const pack=box(g,0,1.28,.34,.48,.6,.18,gear);box(g,.2,1.32,-.35,.1,.1,.75,gear,.1);for(const s of [-1,1]){cyl(g,s*.17,.42,0,.105,.12,.65,uniform,7);cyl(g,s*.39,1.28,0,.09,.11,.58,uniform,7).rotation.z=s*.28;}const eye=sphere(g,0,1.82,-.205,.045,mats.red);eye.scale.set(1,.55,.3);const enemy={group:g,health:100,alive:true,cool:.6+Math.random()*1.5,speed:1.05+Math.random()*.42,flash:0,mark:0,body};enemies.push(enemy);return enemy;}
function spawnWave(i){const count=i===0?3:4;for(let j=0;j<count;j++){let side=j%2===0?-1:1;makeEnemy(side*(4.8+Math.random()*2),relays[i].z-7-Math.random()*12);}}
function shoot(){if(!started||gameOver||reloading)return;const now=performance.now();if(now-lastShot<165)return;lastShot=now;if(player.ammo<=0){reload();return}player.ammo--;$('#ammo').textContent=player.ammo;shotKick=.045;gun.position.z=.04;setTimeout(()=>gun.position.z=0,45);const dir=new THREE.Vector3();camera.getWorldDirection(dir);raycaster.set(camera.position,dir);let best=null,bestDist=36;
 for(const e of enemies){if(!e.alive)continue;const center=e.group.position.clone().add(new THREE.Vector3(0,1.15,0));const to=center.clone().sub(camera.position);const along=to.dot(dir);if(along<0||along>bestDist)continue;const miss=to.addScaledVector(dir,-along).length();if(miss<.62){best=e;bestDist=along;}}
 if(best){best.health-=50;best.flash=.12;$('#hitmarker').classList.add('show');setTimeout(()=>$('#hitmarker').classList.remove('show'),100);if(best.health<=0){best.alive=false;best.group.rotation.x=Math.PI/2;best.group.position.y=-.2;toastTimer=Math.max(toastTimer,.65)}}
}
function reload(){if(reloading||player.ammo===30||player.reserve<=0)return;reloading=true;$('#ammo').style.opacity='.45';setTimeout(()=>{const n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;$('#ammo').textContent=player.ammo;$('#ammo').style.opacity='1';reloading=false;},1000)}
function usePulse(){if(!started||gameOver||pulseCooldown>0)return;pulseLeft=2.5;pulseCooldown=14;for(const e of enemies)if(e.alive){e.mark=5;e.cool=Math.max(e.cool,2.5)}$('#pulse-state').textContent='PULSE ACTIVE · HOSTILES DISRUPTED';$('#pulse-card').classList.add('active');toast('SONAR PULSE · HOSTILES DISRUPTED');const flash=new THREE.PointLight(0xbde95b,9,24);flash.position.copy(camera.position);scene.add(flash);effects.push({object:flash,life:.45,max:.45});}

function updateEnemies(dt){for(const e of enemies){if(!e.alive)continue;e.cool-=dt;e.mark=Math.max(0,e.mark-dt);const ep=e.group.position;const dx=player.pos.x-ep.x,dz=player.pos.z-ep.z,dist=Math.hypot(dx,dz);if(dist>7){ep.x+=dx/dist*e.speed*dt;ep.z+=dz/dist*e.speed*dt;}e.group.rotation.y=Math.atan2(dx,dz);if(dist<20&&e.cool<=0){e.cool=1.35+Math.random()*1.1;if(pulseLeft<=0&&Math.random()<.78){enemyBullets.push({pos:ep.clone().add(new THREE.Vector3(0,1.4,0)),vel:new THREE.Vector3(dx,0,dz).normalize().multiplyScalar(8),life:2});}}
  if(e.mark>0){e.group.traverse(o=>{if(o.isMesh)o.material.emissive?.setHex(0x9bad35);});}else e.group.traverse(o=>{if(o.isMesh&&o.material.emissive)o.material.emissive.setHex(o===e.group.children[2]?0x682511:0x000000);});
 }
 for(let i=enemyBullets.length-1;i>=0;i--){const b=enemyBullets[i];b.pos.addScaledVector(b.vel,dt);b.life-=dt;if(b.life<=0){enemyBullets.splice(i,1);continue}if(b.pos.distanceTo(camera.position)<.72){enemyBullets.splice(i,1);player.health-=9;hitFlash=.22;$('#health-number').textContent=Math.max(0,Math.ceil(player.health));$('#health-fill').style.width=Math.max(0,player.health)+'%';$('#damage-vignette').classList.add('hit');if(player.health<=0)finish(false);}}
}
function updateWorld(dt){elapsed+=dt;tide-=dt;if(tide<=0){finish(false,'THE TIDE CUT OFF THE CAUSEWAY');return}const active=relays[objectiveIndex];for(let i=0;i<relays.length;i++){let r=relays[i];r.ring.rotation.z+=dt*.32;if(i<objectiveIndex){r.light.intensity=2.8;r.group.children[3].material=mats.lime;}else if(i===objectiveIndex){r.light.intensity=1.5+Math.sin(elapsed*3)*.65;r.group.children[3].material=mats.red;}else r.light.intensity=.35;}
 if(active){const d=Math.hypot(player.pos.x-active.group.position.x,player.pos.z-active.group.position.z);$('#distance').textContent=`${Math.round(d)} M`;$('#marker-distance').textContent=`RELAY 0${objectiveIndex+1} · ${Math.round(d)}M`;if(d<5.3){const hostiles=enemies.some(e=>e.alive&&Math.hypot(e.group.position.x-player.pos.x,e.group.position.z-player.pos.z)<8);if(!hostiles)capture=Math.min(10,capture+dt);else capture=Math.max(0,capture-dt*.3);}else capture=Math.max(0,capture-dt*.18);$('#capture-fill').style.width=`${capture*10}%`;$('#capture-label').textContent=d<5.3?(enemies.some(e=>e.alive&&Math.hypot(e.group.position.x-player.pos.x,e.group.position.z-player.pos.z)<8)?'CLEAR HOSTILES':'UPLINK CHARGING'):'MOVE INTO UPLINK ZONE';if(capture>=10){active.active=true;objectiveIndex++;capture=0;if(objectiveIndex>=3){exlight.intensity=3;$('#objective-title').textContent='REACH THE EXTRACTION';$('#objective-count').textContent='EXTRACT';$('#objective-copy').textContent='The channel is live. Make for the flare at the end of the causeway.';toast('ALL RELAYS ONLINE · MOVE TO EXTRACTION');}else{$('#objective-count').textContent=`0${objectiveIndex+1} / 03`;$('#objective-title').textContent=['RE-LIGHT THE BEACON','POWER THE TIDAL GATE','OPEN THE EVAC CHANNEL'][objectiveIndex];$('#objective-copy').textContent='Secure the relay uplink. Hold the perimeter until the signal locks.';toast(`RELAY 0${objectiveIndex} SECURED`);spawnWave(objectiveIndex);}}}
 else {const d=Math.hypot(player.pos.x,player.pos.z+51);$('#distance').textContent=`${Math.round(d)} M`;$('#marker-distance').textContent=`EXTRACT · ${Math.round(d)}M`;$('#capture-label').textContent='EVAC CHANNEL OPEN';$('#capture-fill').style.width='100%';if(d<4)finish(true);}
 $('#clock').textContent=`${Math.floor(tide/60).toString().padStart(2,'0')}:${Math.floor(tide%60).toString().padStart(2,'0')}`;$('#health-fill').style.width=`${Math.max(0,player.health)}%`;$('#health-number').textContent=Math.max(0,Math.ceil(player.health));$('#objective-marker').style.opacity=1;$('#bearing').textContent=Math.abs(yaw)<.8?'N':yaw>0?'W':'E';$('#pulse-ring').classList.toggle('cooling',pulseCooldown>0);$('#pulse-ring').querySelector('span').textContent=pulseCooldown>0?Math.ceil(pulseCooldown):'Q';$('#pulse-state').textContent=pulseCooldown>0?`RECHARGING · ${Math.ceil(pulseCooldown)} SEC`:'READY · REVEALS HOSTILES';$('#pulse-card').classList.toggle('active',pulseLeft>0);
}
function finish(win,reason=''){gameOver=true;document.exitPointerLock?.();$('#end-screen').classList.remove('hidden');$('#end-title').innerHTML=win?'SIGNAL<br /><em>RESTORED.</em>':'MISSION<br /><em>FAILED.</em>';$('#end-copy').textContent=win?'The evacuation channel is open. The causeway holds—for now. Good work, Ranger.':reason||'You were overwhelmed before the evacuation channel came online. The squad will regroup.';$('#end-kicker').innerHTML=win?'<span></span> MISSION COMPLETE · NORTH CAUSEWAY':'<span></span> MISSION REPORT · SIGNAL LOST';}

function movePlayer(dt){let f=Number(keys.KeyW||keys.ArrowUp)-Number(keys.KeyS||keys.ArrowDown),s=Number(keys.KeyD)-Number(keys.KeyA);if(!f&&!s)return;const sprint=keys.ShiftLeft||keys.ShiftRight;let speed=sprint?7.2:4.7;const len=Math.hypot(f,s)||1;f/=len;s/=len;player.pos.x+=(Math.cos(yaw)*s+Math.sin(yaw)*f)*speed*dt;player.pos.z+=(-Math.cos(yaw)*f+Math.sin(yaw)*s)*speed*dt;player.pos.x=THREE.MathUtils.clamp(player.pos.x,-5.7,5.7);player.pos.z=THREE.MathUtils.clamp(player.pos.z,-55,19);}
function update(dt){if(!started||gameOver){renderer.render(scene,camera);return}pulseCooldown=Math.max(0,pulseCooldown-dt);pulseLeft=Math.max(0,pulseLeft-dt);if(pulseLeft===0)$('#pulse-card').classList.remove('active');if(fireDown)shoot();movePlayer(dt);camera.position.set(player.pos.x,1.65,player.pos.z);camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0);shotKick=Math.max(0,shotKick-dt*.3);camera.rotation.x-=shotKick;updateEnemies(dt);updateWorld(dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show')}if(hitFlash>0){hitFlash-=dt;if(hitFlash<=0)$('#damage-vignette').classList.remove('hit')}
 for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;e.object.intensity=9*Math.max(0,e.life/e.max);if(e.life<=0){scene.remove(e.object);effects.splice(i,1)}}renderer.render(scene,camera);}
let last=performance.now();function loop(now){const dt=Math.min(.05,(now-last)/1000);last=now;update(dt);requestAnimationFrame(loop)}requestAnimationFrame(loop);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});
// First contact arrives with the opening warning wave.
spawnWave(0);

