import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const mount=document.querySelector('#game'),scene=new THREE.Scene();scene.background=new THREE.Color(0x91a69f);scene.fog=new THREE.FogExp2(0x91a69f,.018);
